dialog.showMessageBox(window, {
          type: 'question', title: '首次连接中央节点', message: input.profile.host,
          detail: `当前管理员电脑尚未连接过这台服务器。请确认地址无误；确认后，本机会记住服务器身份，后续连接将自动验证。\n\n技术信息：${fingerprint}`,
          buttons: ['取消', '确认并连接'], defaultId: 0, cancelId: 0,
        })

catch (e: any) {
          if (task.phase === 'completed') task.phase = 'verifying';
          task.status = 'error'; task.error = failureMessage(task, e.message);
          try { await this.store.save(); }
          catch (saveError: any) { task.error += '；传输状态保存失败：' + saveError.message + '。请恢复本地存储后重试，将复用原目标。'; }
        }

dialog.showMessageBox(owner, {
        type: 'question', title: '首次连接中央节点', message: p.profile.name || '团队中央节点',
        detail: `这是本机第一次连接 ${p.profile.host}:${p.profile.port}，请确认服务器地址填写正确。`,
        buttons: ['取消', '继续登录'], defaultId: 0, cancelId: 0,
        })
